namespace h=z4c::hyperboloidal;namespace c=cubed_sphere;namespace p=composed_metric_probe;using V=p::V;
constexpr int ti[6]={0,0,0,1,1,2},tj[6]={0,1,2,1,2,2};
h::VectorJet<Real> Smooth(const Real*x){c::Jet X[3];for(int a=0;a<3;++a)X[a]=c::Jet::Variable(x[a],a);const auto o=c::Jet(1)-X[0]*X[0]-X[1]*X[1]-X[2]*X[2];c::Jet a[3]={c::Jet(1)+c::Jet(.2)*X[0]-c::Jet(.3)*X[1],c::Jet(.3)+c::Jet(.4)*X[1]*X[2],c::Jet(-.2)+c::Jet(.5)*X[0]*X[2]};h::VectorJet<Real>b{};for(int v=0;v<3;++v){const auto f=o*o*a[v];b.value[v]=f.f;for(int d=0;d<3;++d){b.d[d][v]=f.d[d];for(int j=0;j<3;++j)b.dd[d][j][v]=f.h[d][j];}}return b;}
struct Region {size_t count=0;long double volume=0,beta2=0,E=0,Q=0,Ead=0,Qad=0,absolute_defect=0;void Add(Real w,Real b2,Real energy,Real strain,Real exactE,Real exactQ){++count;volume+=w;beta2+=w*b2;E+=w*energy;Q+=w*strain;Ead+=w*exactE;Qad+=w*exactQ;absolute_defect+=w*std::abs(energy-strain);}};
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{
 if(argc!=4)throw std::runtime_error("witness_csv outputprefix repaired0or1");const int n=6;c::CompositeMesh mesh(.25,{.45,.55,.60,.65,.70,.75,1},1,n,2,2);h::CompositeShiftStage stage(mesh,4,true,true,true,false);const bool repaired=std::stoi(argv[3]);const size_t replaced=repaired?interface_probe::InjectRepairedInterface(stage.grid):0;const auto&g=stage.grid;const size_t N=g.active.size();c::ScriSurface surface(g,6,7);std::vector<p::U>bulk(N),edge(surface.rows.size());std::vector<h::MetricJet<Real>>metrics;for(auto&u:bulk){u.alpha.value=u.chi.value=1;for(int a=0;a<3;++a)u.metric.g[a][a]=1;metrics.push_back(u.metric);}for(auto&u:edge){u.alpha.value=u.chi.value=1;for(int a=0;a<3;++a)u.metric.g[a][a]=1;}stage.SetGeometry(metrics);p::Operator candidate(stage,surface,bulk,edge);
 V witness(3*N),saved(3*N);std::ifstream input(argv[1]);std::string line;std::getline(input,line);size_t rows=0;while(std::getline(input,line)){if(line.empty())continue;std::replace(line.begin(),line.end(),',',' ');std::istringstream s(line);Real a[17];for(auto&v:a)if(!(s>>v))throw std::runtime_error("witness row shape");if(rows>=N||a[0]!=rows||a[1]!=rows/216)throw std::runtime_error("witness point order");for(int v=0;v<3;++v){if(a[5+v]!=g.geometry[rows].x[v])throw std::runtime_error("witness coordinate notbitwise equal");witness[3*rows+v]=a[11+v];saved[3*rows+v]=a[14+v];}++rows;}if(rows!=N)throw std::runtime_error("witness rows mismatch");std::cout<<std::setprecision(17)<<"{\"cells\":"<<N<<",\"cases\":{";
 bool energy_pass=true;for(int control=0;control<2;++control){const char*name=control?"smooth_zero_boundary":"negative_physical_witness";V beta=witness;if(control)for(size_t k=0;k<N;++k){auto b=Smooth(g.geometry[k].x);for(int v=0;v<3;++v)beta[3*k+v]=b.value[v];}V rates,trace,az;candidate.Rates(beta,rates,trace);candidate.Apply(beta,az);std::map<std::string,Region>regions;Real fresh=0;std::ofstream out(std::string(argv[2])+"."+name+".csv");out<<std::setprecision(17)<<"point,block,i,j,k,face,layer,x,y,z,volume,beta0,beta1,beta2,Az0,Az1,Az2,H00,H01,H02,H11,H12,H22,beta2_density,E_density,Q_density,defect_density,analytic_E_density,analytic_Q_density\n";
  for(size_t k=0;k<N;++k){const int m=k/216,i=k%n,j=k/n%n,l=k/(n*n)%n;const auto&b=g.mesh.blocks[m];const auto&x=g.geometry[k].x;Real b2=0,E=0,Q=0,exactE=0,exactQ=0;for(int v=0;v<3;++v){b2+=beta[3*k+v]*beta[3*k+v];E+=beta[3*k+v]*az[3*k+v];if(!control)fresh=std::max(fresh,std::abs(az[3*k+v]-saved[3*k+v]));}for(int t=0;t<6;++t)Q+=.5*(ti[t]==tj[t]?1:2)*rates[6*k+t]*rates[6*k+t];if(control){auto exact=Smooth(x);Real L[3];h::ApplyEllipticShift(bulk[k].metric,h::Geometry(bulk[k].metric),exact,L);const auto H=h::ShiftMetricRate(bulk[k].metric,exact);for(int v=0;v<3;++v)exactE-=exact.value[v]*L[v];for(int a=0;a<3;++a)for(int b=0;b<3;++b)exactQ+=.5*H.h[a][b]*H.h[a][b];}
   const bool band=i<2||i>=n-2||j<2||j>=n-2||l<2||l>=n-2;std::vector<std::string>names{"all",b.face<0?"cartesian":"shells",band?"any_patch_stencil_band":"patch_bulk"};if(b.face>=0)names.push_back("shell_layer_"+std::to_string(b.layer));if(b.face>=0&&b.layer==6&&i>=n-2)names.push_back("scri_stencil_band");if(b.face<0&&(std::abs(x[0])>.16||std::abs(x[1])>.16||std::abs(x[2])>.16))names.push_back("cartesian_near_cube_interface");for(const auto&region:names)regions[region].Add(g.volumes[k],b2,E,Q,exactE,exactQ);
   out<<k<<','<<m<<','<<i<<','<<j<<','<<l<<','<<b.face<<','<<b.layer;for(Real v:x)out<<','<<v;out<<','<<g.volumes[k];for(const auto*field:{&beta,&az})for(int v=0;v<3;++v)out<<','<<(*field)[3*k+v];for(int t=0;t<6;++t)out<<','<<rates[6*k+t];out<<','<<b2<<','<<E<<','<<Q<<','<<E-Q<<','<<exactE<<','<<exactQ<<'\n';
  }
  energy_pass=energy_pass&&regions.at("all").E>=0;
  std::cout<<(control?",":"")<<'"'<<name<<"\":{\"fresh_Az_max_difference\":"<<fresh<<",\"regions\":{";bool comma=false;for(const auto&[r,v]:regions){std::cout<<(comma?",":"")<<'"'<<r<<"\":{\"cells\":"<<v.count<<",\"volume\":"<<v.volume<<",\"beta2_integral\":"<<v.beta2<<",\"energy_integral\":"<<v.E<<",\"positive_strain_integral\":"<<v.Q<<",\"defect_integral\":"<<v.E-v.Q<<",\"rayleigh\":"<<v.E/v.beta2<<",\"positive_strain_over_beta2\":"<<v.Q/v.beta2<<",\"absolute_defect_integral\":"<<v.absolute_defect<<",\"analytic_energy_same_quadrature\":"<<v.Ead<<",\"analytic_strain_same_quadrature\":"<<v.Qad<<'}';comma=true;}std::cout<<"}}";
 }
 std::cout<<"},\"beta_boundary_exactly_zero\":true,\"physical_volume\":\"mapvol (flat metric,chi=1), noOmega factor\",\"strain_definition\":\"0.5 sum_ij H_ij^2, offdiagonal counted twice\",\"regional_differences_include_crossregion_flux\":true,\"no_evolution_or_Arnoldi_rerun_or_operator_adoption\":true}\n";
 if(!energy_pass)throw std::runtime_error("negative energy witness persists");
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
